    },
    data: { timeoutMs: 30_000, http: { method: 'POST', pathPrefix: '/stripe' } },
    timeout: 35_000,
  });
  expect(res.status(), 'Stripe never called the webhook').toBe(200);
}); curl -sS -X POST "https://api.devhelm.io/api/v1/webhook/inboxes/$INBOX_ID/wait" \
